# Derived sets used by simulation_engine.py
NOT_SUITABLE_PORTS = {
    p for p, v in PORT_SUITABILITY.items()
    if v["status"] == "NOT_SUITABLE"
}

RESTRICTED_PORTS = {
    p: v for p, v in PORT_SUITABILITY.items()
    if v["status"] == "RESTRICTED"
}

